import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Plus, Package, Upload, CheckCircle } from 'lucide-react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';

interface FulfillmentRequestFormProps {
  products: Array<{ id: string; name: string; }>;
}

export function FulfillmentRequestForm({ products }: FulfillmentRequestFormProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [isOpen, setIsOpen] = useState(false);
  const [formData, setFormData] = useState({
    productName: '',
    characteristics: '',
    quantity: '',
    costPrice: '',
    category: '',
    description: '',
    priority: 'medium',
  });
  const [imageFile, setImageFile] = useState<File | null>(null);

  const createRequestMutation = useMutation({
    mutationFn: async (data: any) => {
      const requestData = {
        requestType: 'product_preparation',
        title: `${data.productName} - Fulfillmentga Topshirish So'rovi`,
        description: `Mahsulot: ${data.productName}\nHususiyatlari: ${data.characteristics}\nSoni: ${data.quantity} dona\nTannarx: ${data.costPrice} UZS\nKategoriya: ${data.category}\n\nQo'shimcha ma'lumot: ${data.description}`,
        priority: data.priority,
        estimatedCost: data.costPrice,
        metadata: {
          productDetails: {
            name: data.productName,
            characteristics: data.characteristics,
            quantity: parseInt(data.quantity),
            costPrice: parseFloat(data.costPrice),
            category: data.category,
            hasImage: !!imageFile
          }
        }
      };

      return await apiRequest('POST', '/api/fulfillment-requests', requestData);
    },
    onSuccess: () => {
      toast({
        title: "Muvaffaqiyat!",
        description: "Fulfillment so'rovi yuborildi. Admin tomonidan ko'rib chiqiladi.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/fulfillment-requests'] });
      resetForm();
      setIsOpen(false);
    },
    onError: (error: Error) => {
      toast({
        title: "Xatolik!",
        description: error.message || "So'rov yaratishda xatolik yuz berdi.",
        variant: "destructive",
      });
    },
  });

  const resetForm = () => {
    setFormData({
      productName: '',
      characteristics: '',
      quantity: '',
      costPrice: '',
      category: '',
      description: '',
      priority: 'medium',
    });
    setImageFile(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.productName.trim() || !formData.characteristics.trim() || 
        !formData.quantity || !formData.costPrice || !formData.category) {
      toast({
        title: "Xatolik!",
        description: "Barcha majburiy maydonlarni to'ldiring.",
        variant: "destructive",
      });
      return;
    }

    createRequestMutation.mutate(formData);
  };

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={setIsOpen}>
      <DialogTrigger asChild>
        <Button className="bg-blue-600 hover:bg-blue-700" data-testid="button-new-request">
          <Plus className="w-4 h-4 mr-2" />
          Fulfillmentga So'rov Yuborish
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-[700px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Package className="w-5 h-5 text-blue-600" />
            Mahsulot Fulfillmentga Topshirish So'rovi
          </DialogTitle>
          <DialogDescription className="text-sm text-slate-600 mt-2">
            Mahsulotingizni fulfillmentga topshirish uchun barcha ma'lumotlarni to'ldiring. 
            Fulfillment jamoasi mahsulotingizni qabul qilib, marketplace tayyorlashdan boshlab barcha jarayonlarni amalga oshiradi.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Product Name */}
          <div className="space-y-2">
            <Label htmlFor="productName" className="text-sm font-medium">
              Mahsulot Nomi <span className="text-red-500">*</span>
            </Label>
            <Input
              id="productName"
              value={formData.productName}
              onChange={(e) => handleInputChange('productName', e.target.value)}
              placeholder="Masalan: iPhone 15 Pro Max 256GB"
              data-testid="input-product-name"
              className="w-full"
            />
          </div>

          {/* Characteristics */}
          <div className="space-y-2">
            <Label htmlFor="characteristics" className="text-sm font-medium">
              Mahsulot Hususiyatlari <span className="text-red-500">*</span>
            </Label>
            <Textarea
              id="characteristics"
              value={formData.characteristics}
              onChange={(e) => handleInputChange('characteristics', e.target.value)}
              placeholder="Masalan: Rang: Titanium Blue, Xotira: 256GB, Ekran: 6.7 dyuym, Kamera: 48MP, Batareya: 4441mAh"
              rows={3}
              data-testid="textarea-characteristics"
            />
            <p className="text-xs text-slate-500">
              Mahsulotning barcha muhim xususiyatlarini kiriting (rang, o'lchami, texnik ko'rsatkichlar va boshqalar)
            </p>
          </div>

          {/* Quantity and Cost Price */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="quantity" className="text-sm font-medium">
                Miqdori (dona) <span className="text-red-500">*</span>
              </Label>
              <Input
                id="quantity"
                type="number"
                min="1"
                value={formData.quantity}
                onChange={(e) => handleInputChange('quantity', e.target.value)}
                placeholder="10"
                data-testid="input-quantity"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="costPrice" className="text-sm font-medium">
                Tannarx (UZS) <span className="text-red-500">*</span>
              </Label>
              <Input
                id="costPrice"
                type="number"
                min="0"
                value={formData.costPrice}
                onChange={(e) => handleInputChange('costPrice', e.target.value)}
                placeholder="15000000"
                data-testid="input-cost-price"
              />
            </div>
          </div>

          {/* Category */}
          <div className="space-y-2">
            <Label htmlFor="category" className="text-sm font-medium">
              Kategoriya <span className="text-red-500">*</span>
            </Label>
            <Select value={formData.category} onValueChange={(value) => handleInputChange('category', value)}>
              <SelectTrigger data-testid="select-category">
                <SelectValue placeholder="Mahsulot kategoriyasini tanlang" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="electronics">📱 Elektronika</SelectItem>
                <SelectItem value="clothing">👕 Kiyim va poyabzal</SelectItem>
                <SelectItem value="home">🏠 Uy va bog'</SelectItem>
                <SelectItem value="beauty">💄 Go'zallik va salomatlik</SelectItem>
                <SelectItem value="sports">⚽ Sport va faol dam olish</SelectItem>
                <SelectItem value="books">📚 Kitoblar</SelectItem>
                <SelectItem value="toys">🧸 O'yinchoqlar va bolalar buyumlari</SelectItem>
                <SelectItem value="automotive">🚗 Avtomobil tovar va aksessuarlar</SelectItem>
                <SelectItem value="food">🍎 Oziq-ovqat mahsulotlari</SelectItem>
                <SelectItem value="other">📦 Boshqa</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Image Upload */}
          <div className="space-y-2">
            <Label className="text-sm font-medium">Mahsulot Rasmi</Label>
            <div className="border-2 border-dashed border-slate-300 rounded-lg p-6 text-center hover:border-blue-400 transition-colors">
              <input
                type="file"
                accept="image/*"
                onChange={handleImageChange}
                className="hidden"
                id="image-upload"
                data-testid="input-image"
              />
              <Label htmlFor="image-upload" className="cursor-pointer">
                <div className="flex flex-col items-center gap-3">
                  {imageFile ? (
                    <>
                      <CheckCircle className="w-8 h-8 text-green-500" />
                      <span className="text-sm font-medium text-green-700">{imageFile.name}</span>
                      <span className="text-xs text-slate-500">Rasmni o'zgartirish uchun bosing</span>
                    </>
                  ) : (
                    <>
                      <Upload className="w-8 h-8 text-slate-400" />
                      <span className="text-sm font-medium text-slate-700">Mahsulot rasmini yuklang</span>
                      <span className="text-xs text-slate-500">PNG, JPG yoki JPEG formatida (maksimal 5MB)</span>
                    </>
                  )}
                </div>
              </Label>
            </div>
          </div>

          {/* Additional Description */}
          <div className="space-y-2">
            <Label htmlFor="description" className="text-sm font-medium">
              Qo'shimcha Ma'lumot
            </Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => handleInputChange('description', e.target.value)}
              placeholder="Maxsus talablar, qadoqlash ko'rsatmalari, muhim eslatmalar va boshqa zarur ma'lumotlar..."
              rows={3}
              data-testid="textarea-description"
            />
          </div>

          {/* Priority */}
          <div className="space-y-2">
            <Label htmlFor="priority" className="text-sm font-medium">
              Muhimlik Darajasi
            </Label>
            <Select value={formData.priority} onValueChange={(value) => handleInputChange('priority', value)}>
              <SelectTrigger data-testid="select-priority">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="low">🟢 Past - Odatiy jarayon (7-10 kun)</SelectItem>
                <SelectItem value="medium">🟡 O'rta - Standart (5-7 kun)</SelectItem>
                <SelectItem value="high">🟠 Yuqori - Tezroq qayta ishlash (3-5 kun)</SelectItem>
                <SelectItem value="urgent">🔴 Shoshilinch - 1-2 kun ichida</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="flex justify-end gap-3 pt-6 border-t">
            <Button
              type="button"
              variant="outline"
              onClick={() => setIsOpen(false)}
              data-testid="button-cancel"
            >
              Bekor qilish
            </Button>
            <Button
              type="submit"
              disabled={createRequestMutation.isPending}
              className="bg-blue-600 hover:bg-blue-700"
              data-testid="button-submit"
            >
              {createRequestMutation.isPending ? 'Yuborilmoqda...' : "So'rov Yuborish"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/LoginForm.tsx.content:
import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { LogIn, Eye, EyeOff, ArrowLeft } from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';

interface LoginFormProps {
  onSuccess?: () => void;
  isAdmin?: boolean;
}

export function LoginForm({ onSuccess, isAdmin = false }: LoginFormProps) {
  const { login } = useAuth();
  const [formData, setFormData] = useState({
    username: '',
    password: '',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      const result = await login(formData.username, formData.password);
      if (result?.user?.role === 'admin') {
        window.location.href = '/admin-panel';
      } else if (result?.user?.role === 'partner') {
        window.location.href = '/partner-dashboard';
      } else {
        onSuccess?.();
      }
    } catch (error: any) {
      setError(error.message || 'Kirish jarayonida xatolik yuz berdi');
    } finally {
      setIsLoading(false);
    }
  };

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  return (
    <Card className="w-full max-w-md mx-auto shadow-xl">
      <CardHeader className="text-center">
        <div className="flex justify-start mb-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => window.location.href = '/'}
            className="flex items-center gap-2 text-slate-600 hover:text-slate-900"
            data-testid="button-back-to-home"
          >
            <ArrowLeft className="w-4 h-4" />
            Bosh sahifaga qaytish
          </Button>
        </div>
        <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-4">
          <LogIn className="w-8 h-8 text-primary" />
        </div>
        <CardTitle className="text-2xl font-bold">
          {isAdmin ? 'Admin Paneli' : 'Partner Kirish'}
        </CardTitle>
        <p className="text-slate-600">
          {isAdmin ? 'Admin hisobingizga kiring' : 'Partner hisobingizga kiring'}
        </p>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          {error && (
            <Alert variant="destructive">
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}

          <div>
            <Label htmlFor="username">Username</Label>
            <Input
              id="username"
              value={formData.username}
              onChange={(e) => handleInputChange('username', e.target.value)}
              placeholder="Username kiriting"
              required
              data-testid="input-username"
            />
          </div>

          <div>
            <Label htmlFor="password">Parol</Label>
            <div className="relative">
              <Input
                id="password"
                type={showPassword ? 'text' : 'password'}
                value={formData.password}
                onChange={(e) => handleInputChange('password', e.target.value)}
                placeholder="Parol kiriting"
                required
                data-testid="input-password"
              />
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="absolute right-2 top-1/2 transform -translate-y-1/2 h-auto p-1"
                onClick={() => setShowPassword(!showPassword)}
              >
                {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </Button>
            </div>
          </div>

          <Button 
            type="submit" 
            className="w-full"
            disabled={isLoading}
            data-testid="button-login"
          >
            {isLoading ? 'Kirilmoqda...' : 'Kirish'}
          </Button>
        </form>

        {!isAdmin && (
          <div className="text-center mt-6">
            <p className="text-slate-600 text-sm">
              Hali hamkor emassizmi?{' '}
              <button
                onClick={() => window.location.href = '/partner-registration'}
                className="text-primary hover:underline font-medium"
              >
                Ro'yxatdan o'ting
              </button>
            </p>
          </div>
        )}

        {isAdmin && (
          <div className="text-center mt-6">
            <p className="text-slate-600 text-sm">
              Default: admin / admin123
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

client/src/components/MarketplaceApiConf.content:
import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useToast } from '@/hooks/use-toast';
import { apiRequest } from '@/lib/queryClient';
import { 
  Zap, 
  Settings, 
  Globe, 
  Key, 
  Wifi, 
  WifiOff,
  Save,
  RefreshCw,
  AlertTriangle,
  CheckCircle,
  XCircle,
  ExternalLink,
  Database,
  Shield
} from 'lucide-react';

interface ApiConfig {
  id: string;
  marketplace: string;
  apiKey: string;
  apiSecret: string;
  shopId: string;
  baseUrl: string;
  webhookUrl: string;
  isActive: boolean;
  status: 'connected' | 'disconnected' | 'error';
  lastSync: string | null;
  errorMessage?: string;
  rateLimit: number;
  timeout: number;
}

export function MarketplaceApiConfig() {
  const [selectedMarketplace, setSelectedMarketplace] = useState('uzum');
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Get all marketplace API configurations
  const { data: apiConfigs = [], isLoading } = useQuery<ApiConfig[]>({
    queryKey: ['/api/admin/marketplace-configs'],
  });

  // Test API connection mutation
  const testConnectionMutation = useMutation({
    mutationFn: async (marketplace: string) => {
      const response = await fetch(`/api/admin/marketplace-configs/${marketplace}/test`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });
      if (!response.ok) throw new Error('Ulanish test qilishda xatolik');
      return response.json();
    },
    onSuccess: (data) => {
      toast({
        title: "Ulanish muvaffaqiyatli",
        description: `${data.marketplace} bilan ulanish ishlaydi`,
      });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/marketplace-configs'] });
    },
    onError: (error: any) => {
      toast({
        title: "Ulanish xatosi",
        description: error.message || "API ulanishini test qilishda muammo",
        variant: "destructive"
      });
    },
  });

  // Save API configuration mutation
  const saveConfigMutation = useMutation({
    mutationFn: async (config: Partial<ApiConfig>) => {
      const response = await fetch(`/api/admin/marketplace-configs/${config.marketplace}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(config),
      });
      if (!response.ok) throw new Error('Konfiguratsiyani saqlashda xatolik');
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Saqlandi",
        description: "API konfiguratsiya muvaffaqiyatli saqlandi",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/marketplace-configs'] });
    },
    onError: (error: any) => {
      toast({
        title: "Saqlash xatosi",
        description: error.message || "Konfiguratsiyani saqlashda muammo",
        variant: "destructive"
      });
    },
  });

  // Sync marketplace data mutation
  const syncDataMutation = useMutation({
    mutationFn: async (marketplace: string) => {
      const response = await fetch(`/api/admin/marketplace-configs/${marketplace}/sync`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });
      if (!response.ok) throw new Error('Ma\'lumotlarni sinxronlashda xatolik');
      return response.json();
    },
    onSuccess: (data) => {
      toast({
        title: "Sinxronlash boshlandi",
        description: `${data.marketplace} ma'lumotlari yangilanmoqda`,
      });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/marketplace-configs'] });
    },
    onError: (error: any) => {
      toast({
        title: "Sinxronlash xatosi",
        description: error.message || "Ma'lumotlarni sinxronlashda muammo",
        variant: "destructive"
      });
    },
  });

  const marketplaces = [
    { id: 'uzum', name: 'Uzum Market', icon: '🛍️' },
    { id: 'wildberries', name: 'Wildberries', icon: '🟣' },
    { id: 'yandex', name: 'Yandex Market', icon: '🟡' },
    { id: 'aliexpress', name: 'AliExpress', icon: '🔸' },
    { id: 'amazon', name: 'Amazon', icon: '📦' },
    { id: 'ozon', name: 'Ozon', icon: '🔵' }
  ];

  const selectedConfig = apiConfigs.find(config => config.marketplace === selectedMarketplace);

  const handleSaveConfig = (formData: FormData) => {
    const config = {
      marketplace: selectedMarketplace,
      apiKey: formData.get('apiKey') as string,
      apiSecret: formData.get('apiSecret') as string,
      shopId: formData.get('shopId') as string,
      baseUrl: formData.get('baseUrl') as string,
      webhookUrl: formData.get('webhookUrl') as string,
      isActive: formData.get('isActive') === 'on',
      rateLimit: parseInt(formData.get('rateLimit') as string) || 1000,
      timeout: parseInt(formData.get('timeout') as string) || 30000,
    };
    saveConfigMutation.mutate(config);
  };

  if (isLoading) {
    return <div className="animate-pulse bg-slate-200 h-96 rounded-lg"></div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">Marketplace API Konfiguratsiyasi</h2>
        <Button 
          onClick={() => queryClient.invalidateQueries({ queryKey: ['/api/admin/marketplace-configs'] })}
          variant="outline"
          size="sm"
        >
          <RefreshCw className="w-4 h-4 mr-2" />
          Yangilash
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Marketplace Status Overview */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Globe className="w-5 h-5" />
              Marketplace Holati
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {marketplaces.map(marketplace => {
              const config = apiConfigs.find(c => c.marketplace === marketplace.id);
              return (
                <div 
                  key={marketplace.id}
                  className={`flex items-center justify-between p-3 rounded-lg border cursor-pointer transition-colors ${
                    selectedMarketplace === marketplace.id ? 'bg-primary/10 border-primary' : 'hover:bg-slate-50'
                  }`}
                  onClick={() => setSelectedMarketplace(marketplace.id)}
                >
                  <div className="flex items-center gap-3">
                    <span className="text-lg">{marketplace.icon}</span>
                    <div>
                      <p className="font-medium">{marketplace.name}</p>
                      {config?.lastSync && (
                        <p className="text-sm text-slate-500">
                          Oxirgi sinxron: {new Date(config.lastSync).toLocaleDateString('uz-UZ')}
                        </p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {config?.status === 'connected' && <Wifi className="w-4 h-4 text-green-500" />}
                    {config?.status === 'disconnected' && <WifiOff className="w-4 h-4 text-slate-400" />}
                    {config?.status === 'error' && <AlertTriangle className="w-4 h-4 text-red-500" />}
                    <Badge 
                      variant={config?.status === 'connected' ? 'default' : 'secondary'}
                      className="text-xs"
                    >
                      {config?.status === 'connected' ? 'Ulangan' : 
                       config?.status === 'error' ? 'Xato' : 'Ulanmagan'}
                    </Badge>
                  </div>
                </div>
              );
            })}
          </CardContent>
        </Card>

        {/* API Configuration Form */}
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Settings className="w-5 h-5" />
              {marketplaces.find(m => m.id === selectedMarketplace)?.name} API Sozlamalari
            </CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={(e) => {
              e.preventDefault();
              const formData = new FormData(e.currentTarget);
              handleSaveConfig(formData);
            }} className="space-y-6">

              <Tabs defaultValue="credentials" className="w-full">
                <TabsList className="grid w-full grid-cols-3">
                  <TabsTrigger value="credentials">API Ma'lumotlari</TabsTrigger>
                  <TabsTrigger value="settings">Sozlamalar</TabsTrigger>
                  <TabsTrigger value="testing">Test va Monitoring</TabsTrigger>
                </TabsList>

                <TabsContent value="credentials" className="space-y-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <Label htmlFor="apiKey">API Key</Label>
                      <Input
                        id="apiKey"
                        name="apiKey"
                        type="password"
                        placeholder="API kalitingizni kiriting"
                        defaultValue={selectedConfig?.apiKey || ''}
                        data-testid="input-api-key"
                      />
                    </div>
                    <div>
                      <Label htmlFor="apiSecret">API Secret</Label>
                      <Input
                        id="apiSecret"
                        name="apiSecret"
                        type="password"
                        placeholder="API secret kiriting"
                        defaultValue={selectedConfig?.apiSecret || ''}
                        data-testid="input-api-secret"
                      />
                    </div>
                    <div>
                      <Label htmlFor="shopId">Shop ID</Label>
                      <Input
                        id="shopId"
                        name="shopId"
                        placeholder="Do'kon ID kiriting"
                        defaultValue={selectedConfig?.shopId || ''}
                        data-testid="input-shop-id"
                      />
                    </div>
                    <div>
                      <Label htmlFor="baseUrl">Base URL</Label>
                      <Input
                        id="baseUrl"
                        name="baseUrl"
                        placeholder="https://api.marketplace.com"
                        defaultValue={selectedConfig?.baseUrl || ''}
                        data-testid="input-base-url"
                      />
                    </div>
                  </div>
                  <div>
                    <Label htmlFor="webhookUrl">Webhook URL</Label>
                    <Input
                      id="webhookUrl"
                      name="webhookUrl"
                      placeholder="https://biznesyordam.uz/webhooks/marketplace"
                      defaultValue={selectedConfig?.webhookUrl || ''}
                      data-testid="input-webhook-url"
                    />
                  </div>
                </TabsContent>

                <TabsContent value="settings" className="space-y-4">
                  <div className="flex items-center space-x-2">
                    <Switch 
                      id="isActive" 
                      name="isActive"
                      defaultChecked={selectedConfig?.isActive || false}
                      data-testid="switch-is-active"
                    />
                    <Label htmlFor="isActive">API faol</Label>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <Label htmlFor="rateLimit">So'rovlar chegarasi (soatiga)</Label>
                      <Input
                        id="rateLimit"
                        name="rateLimit"
                        type="number"
                        placeholder="1000"
                        defaultValue={selectedConfig?.rateLimit || 1000}
                        data-testid="input-rate-limit"
                      />
                    </div>
                    <div>
                      <Label htmlFor="timeout">Timeout (millisekund)</Label>
                      <Input
                        id="timeout"
                        name="timeout"
                        type="number"
                        placeholder="30000"
                        defaultValue={selectedConfig?.timeout || 30000}
                        data-testid="input-timeout"
                      />
                    </div>
                  </div>
                </TabsContent>

                <TabsContent value="testing" className="space-y-4">
                  <div className="bg-slate-50 p-4 rounded-lg">
                    <h4 className="font-medium mb-3">Ulanish holati</h4>
                    <div className="flex items-center gap-4 mb-4">
                      {selectedConfig?.status === 'connected' && (
                        <>
                          <CheckCircle className="w-5 h-5 text-green-500" />
                          <span className="text-green-700">Muvaffaqiyatli ulangan</span>
                        </>
                      )}
                      {selectedConfig?.status === 'error' && (
                        <>
                          <XCircle className="w-5 h-5 text-red-500" />
                          <span className="text-red-700">Ulanish xatosi</span>
                        </>
                      )}
                      {!selectedConfig?.status && (
                        <>
                          <AlertTriangle className="w-5 h-5 text-yellow-500" />
                          <span className="text-yellow-700">Hali test qilinmagan</span>
                        </>
                      )}
                    </div>

                    {selectedConfig?.errorMessage && (
                      <div className="bg-red-50 border border-red-200 rounded p-3 mb-4">
                        <p className="text-red-700 text-sm">{selectedConfig.errorMessage}</p>
                      </div>
                    )}

                    <div className="flex gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        onClick={() => testConnectionMutation.mutate(selectedMarketplace)}
                        disabled={testConnectionMutation.isPending}
                        data-testid="button-test-connection"
                      >
                        {testConnectionMutation.isPending ? (
                          <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                        ) : (
                          <Zap className="w-4 h-4 mr-2" />
                        )}
                        Ulanishni Test Qilish
                      </Button>

                      <Button
                        type="button"
                        variant="outline"
                        onClick={() => syncDataMutation.mutate(selectedMarketplace)}
                        disabled={syncDataMutation.isPending || selectedConfig?.status !== 'connected'}
                        data-testid="button-sync-data"
                      >
                        {syncDataMutation.isPending ? (
                          <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                        ) : (
                          <Database className="w-4 h-4 mr-2" />
                        )}
                        Ma'lumotlarni Sinxronlash
                      </Button>
                    </div>
                  </div>

                  {selectedConfig?.lastSync && (
                    <div className="bg-blue-50 p-4 rounded-lg">
                      <h4 className="font-medium mb-2">Oxirgi sinxronizatsiya</h4>
                      <p className="text-sm text-blue-700">
                        {new Date(selectedConfig.lastSync).toLocaleString('uz-UZ')}
                      </p>
                    </div>
                  )}
                </TabsContent>
              </Tabs>

              <div className="flex justify-end gap-2 pt-4">
                <Button 
                  type="submit"
                  disabled={saveConfigMutation.isPending}
                  data-testid="button-save-config"
                >
                  {saveConfigMutation.isPending ? (
                    <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                  ) : (
                    <Save className="w-4 h-4 mr-2" />
                  )}
                  Saqlash
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/components/ProductForm.tsx.content:
import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Plus, Package } from 'lucide-react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { apiRequest } from '@/lib/api';
import { useToast } from '@/hooks/use-toast';

interface ProductFormProps {
  products?: Array<{ id: string; name: string; }>;
}

export function ProductForm({ products = [] }: ProductFormProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [isOpen, setIsOpen] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    category: '',
    description: '',
    price: '',
    costPrice: '',
    sku: '',
    barcode: '',
    weight: '',
  });

  const createProductMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      const response = await apiRequest('POST', '/api/products', data);
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Mahsulot yaratildi",
        description: "Mahsulot muvaffaqiyatli yaratildi",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/products'] });
      setIsOpen(false);
      setFormData({
        name: '',
        category: '',
        description: '',
        price: '',
        costPrice: '',
        sku: '',
        barcode: '',
        weight: '',
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Xatolik",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    createProductMutation.mutate(formData);
  };

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  return (
    <Dialog open={isOpen} onOpenChange={setIsOpen}>
      <DialogTrigger asChild>
        <Button className="bg-accent hover:bg-accent/90" data-testid="button-new-product">
          <Plus className="w-4 h-4 mr-2" />
          Yangi Mahsulot
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center">
